# append omitted trailing 0s on three parsed rows
for i in (15,16,17): grid[i].append(0)
# translate source object layers into 14x14; order determines overlap priority
out=[[0]*14 for _ in range(14)]
trans={2:(0,-1),3:(-1,-5),7:(-4,0),8:(-4,-2),5:(-4,0)}
for color in [2,3,7,5,8]:
    dr,dc=trans[color]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==color:
                rr,cc=r+dr,c+dc
                if 0<=rr<14 and 0<=cc<14: out[rr][cc]=color
print('\n'.join(' '.join(map(str,row)) for row in out))
